#include <stdio.h>

int main(void) {
    char op;
    double a, b;
    scanf(" %c %lf %lf", &op, &a, &b);
    double result = 0.0;
    switch (op) {
        case '+': result = a + b; break;
        case '-': result = a - b; break;
        case '*': result = a * b; break;
        case '/':
            if (b != 0.0) {
                result = a / b;
            } else {
                result = 0.0;
            }
            break;
        default: result = 0.0; break;
    }
    printf("%.2f\n", result);
    return 0;
}

