#include <stdio.h>

int main(void) {
    int n, i;
    int under = 0, normal = 0, over = 0, obese = 0;
    scanf("%d", &n);
    for (i = 0; i < n; i++) {
        double w, h;
        scanf("%lf %lf", &w, &h);
        double bmi = w / (h * h);
        if (bmi < 18.5) {
            under++;
        } else if (bmi < 25.0) {
            normal++;
        } else if (bmi < 30.0) {
            over++;
        } else {
            obese++;
        }
    }
    printf("Underweight: %d\n", under);
    printf("Normal: %d\n", normal);
    printf("Overweight: %d\n", over);
    printf("Obese: %d\n", obese);
    return 0;
}

#include <stdio.h>

int main(void) {
    int n, i;
    double balance = 0.0;
    scanf("%d", &n);
    for (i = 0; i < n; i++) {
        char type;
        double amount;
        scanf(" %c %lf", &type, &amount);
        switch (type) {
            case 'D': case 'd':
                balance += amount;
                break;
            case 'W': case 'w':
                if (amount <= balance) {
                    balance -= amount;
                }
                break;
            case 'B': case 'b':
                /* balance check, no change */
                break;
            default:
                break;
        }
    }
    printf("%.2f\n", balance);
    return 0;
}

