                }
                break;
            case 4:
                printf("Report\n");
                break;
            default:
                printf("Invalid\n");
                break;
        }
    }
    return 0;
}

#include <stdio.h>

int main(void) {
    int n, i;
    double total = 0.0;
    scanf("%d", &n);
    for (i = 0; i < n; i++) {
        double weight, distance;
        scanf("%lf %lf", &weight, &distance);
        double cost = 0.0;
        if (weight <= 1.0) {
            cost += 10.0;
        } else if (weight <= 5.0) {
            cost += 20.0;
        } else if (weight <= 10.0) {
            cost += 50.0;
        } else {
            cost += 100.0;
        }
        if (distance <= 100.0) {
            cost += 5.0;
        } else if (distance <= 500.0) {
            cost += 15.0;
        } else {
            cost += 30.0;
        }
        total += cost;
    }
    printf("%.2f\n", total);
    return 0;
}
